"""One independently composed animated SVG per authored event."""
import json,html
from pathlib import Path
root=Path(__file__).resolve().parents[1]
data=json.loads((root/'content/events-v2.json').read_text())
out=root/'public/event-comics';out.mkdir(parents=True,exist_ok=True)
INK='#172e4e';CREAM='#fff0d0';CORAL='#f87964';TEAL='#60c7b7';GOLD='#ffcf69'
def rect(x,y,w,h,c=CREAM,r=8):return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="{r}" fill="{c}" stroke="{INK}" stroke-width="4"/>'
def path(d,c='none',s=INK,w=5,cls=''):return f'<path d="{d}" fill="{c}" stroke="{s}" stroke-width="{w}" stroke-linecap="round" stroke-linejoin="round" class="{cls}"/>'
def text(x,y,s,size=22,c=INK):return f'<text x="{x}" y="{y}" font-size="{size}" font-weight="800" fill="{c}" font-family="sans-serif">{html.escape(s)}</text>'
def person(x,y,c=TEAL,scale=1,female=False,pose='talk'):
 arm=path('M-20 28-53 6M20 28 53-7' if pose=='talk' else 'M-20 28-38 68M20 28 39 66',s=c,w=16)
 hair=path('M-25-42Q-32-70 0-70Q32-69 26-32L18-45Q0-51-19-43Z','#31405d',w=3) if female else path('M-23-48Q-27-69 0-67Q26-66 23-44L10-53-9-49Z','#483849',w=3)
 return f'<g transform="translate({x} {y}) scale({scale})"><g class="move"><ellipse cx="0" cy="115" rx="40" ry="9" fill="{INK}" opacity=".22"/>'+path('M-13 63-19 104M13 63 23 104',s=INK,w=16)+path('M-29 61V23Q-24-7 0-8Q26-6 29 22V61Z',c,w=4)+arm+f'<circle cy="-44" r="23" fill="#edb68e" stroke="{INK}" stroke-width="4"/>'+hair+f'<circle cx="-8" cy="-43" r="2.5" fill="{INK}"/><circle cx="8" cy="-43" r="2.5" fill="{INK}"/>'+path('M-5-31Q0-28 5-31',w=2)+'</g></g>'
def window(x,y,w=72,h=83):return rect(x,y,w,h,'#79bad6')+path(f'M{x+w/2} {y}V{y+h}M{x} {y+h/2}H{x+w}',s='#e4f0ed',w=5)
def wall():return rect(80,80,640,284,'#8da1b3',6)+window(104,106)+window(606,106)
def table(x=190,y=292,w=420):return path(f'M{x} {y}H{x+w}V{y+22}H{x}Z','#b77b61')+path(f'M{x+24} {y+22}V{y+103}M{x+w-24} {y+22}V{y+103}',s='#805742',w=15)
def paper(x,y,w=120,h=85,label=''):return rect(x,y,w,h,'#fffae9',3)+''.join(path(f'M{x+15} {y+20+i*16}H{x+w-15}',s='#6d8e9f',w=3) for i in range(3))+(text(x+12,y+h-8,label,15) if label else '')
def monitor(x,y,w=240,h=155,alert=False):return rect(x,y,w,h,'#1d4561',10)+path(f'M{x+w/2} {y+h}V{y+h+24}M{x+w/2-45} {y+h+25}H{x+w/2+45}',s=INK,w=9)+text(x+25,y+65,'!' if alert else '●',46,CORAL if alert else TEAL)
def tree(x,y,s=1):return f'<g transform="translate({x} {y}) scale({s})">'+path('M0 10V145',s='#785640',w=17)+f'<circle cy="-8" r="54" fill="#458b79" stroke="{INK}" stroke-width="4"/><circle cx="-35" cy="25" r="43" fill="#6cb787" stroke="{INK}" stroke-width="4"/><circle cx="34" cy="16" r="45" fill="#83c794" stroke="{INK}" stroke-width="4"/></g>'
def box(x,y,w=100,h=70,label=''):return rect(x,y,w,h,'#d6a776',3)+path(f'M{x+w/2} {y}V{y+h}',s='#f5d5a4',w=15)+text(x+13,y+45,label,18)
def car(x,y,s=1,color=CREAM,cross=False):return f'<g transform="translate({x} {y}) scale({s})">'+path('M0 0V-62H120L162-21H188V13H0Z',color,w=5)+rect(82,-54,33,31,'#79bad6',3)+rect(121,-41,29,23,'#79bad6',3)+f'<circle cx="36" cy="17" r="20" fill="{INK}"/><circle cx="147" cy="17" r="20" fill="{INK}"/>'+(path('M40-49V-19M25-34H55',s=CORAL,w=8)+rect(55,-72,22,9,CORAL,3) if cross else '')+'</g>'
def bus(x,y,s=1,color=GOLD):return f'<g transform="translate({x} {y}) scale({s})">'+rect(0,-114,320,112,color,14)+''.join(rect(15+i*60,-96,45,47,'#79bad6',5) for i in range(5))+rect(263,-42,42,34,'#486575',3)+f'<circle cx="65" r="25" fill="{INK}"/><circle cx="264" r="25" fill="{INK}"/>'+path('M8-37H244',s=CREAM,w=5)+'</g>'
def clock(x,y,r=49,wrong=False):return f'<circle cx="{x}" cy="{y}" r="{r}" fill="{CREAM}" stroke="{INK}" stroke-width="6"/>'+path(f'M{x} {y-r+10}V{y}L{x+(25 if wrong else -20)} {y+9}',w=5)
def bench(x,y):return rect(x,y,200,35,'#d59d69',4)+rect(x,y-38,200,26,'#d59d69',4)+path(f'M{x+20} {y+35}V{y+76}M{x+180} {y+35}V{y+76}',s=INK,w=10)
def lamp(x,y):return path(f'M{x} {y}V{y-170}Q{x} {y-197} {x+35} {y-190}',s=INK,w=11)+path(f'M{x+14} {y-184}H{x+64}L{x+53} {y-157}H{x+24}Z',GOLD)+f'<path d="M{x+17} {y-155} {x-46} {y}H{x+111}L{x+62} {y-155}Z" fill="{GOLD}" opacity=".13" class="pulse"/>'
